package com.ruoyi.system.domain.shop;
import java.util.Date;
import com.ruoyi.common.annotation.Excel;
import com.ruoyi.common.core.domain.BaseEntity;
public class MallCoupon extends BaseEntity { private Long couponId; @Excel(name="优惠券名称") private String couponName; @Excel(name="门槛金额(分)", cellType=Excel.ColumnType.NUMERIC) private Long thresholdAmount; @Excel(name="优惠金额(分)", cellType=Excel.ColumnType.NUMERIC) private Long discountAmount; @Excel(name="发放总量", cellType=Excel.ColumnType.NUMERIC) private Long totalQuantity; @Excel(name="已领取", cellType=Excel.ColumnType.NUMERIC) private Long receivedQuantity; @Excel(name="已使用", cellType=Excel.ColumnType.NUMERIC) private Long usedQuantity; @Excel(name="每人限领", cellType=Excel.ColumnType.NUMERIC) private Integer limitPerMember; @Excel(name="领取开始", dateFormat="yyyy-MM-dd HH:mm:ss") private Date receiveBeginTime; @Excel(name="领取结束", dateFormat="yyyy-MM-dd HH:mm:ss") private Date receiveEndTime; private Integer validDays; private Date validBeginTime; private Date validEndTime; @Excel(name="状态", readConverterExp="0=启用,1=停用") private String status; public Long getCouponId(){return couponId;} public void setCouponId(Long v){couponId=v;} public String getCouponName(){return couponName;} public void setCouponName(String v){couponName=v;} public Long getThresholdAmount(){return thresholdAmount;} public void setThresholdAmount(Long v){thresholdAmount=v;} public Long getDiscountAmount(){return discountAmount;} public void setDiscountAmount(Long v){discountAmount=v;} public Long getTotalQuantity(){return totalQuantity;} public void setTotalQuantity(Long v){totalQuantity=v;} public Long getReceivedQuantity(){return receivedQuantity;} public void setReceivedQuantity(Long v){receivedQuantity=v;} public Long getUsedQuantity(){return usedQuantity;} public void setUsedQuantity(Long v){usedQuantity=v;} public Integer getLimitPerMember(){return limitPerMember;} public void setLimitPerMember(Integer v){limitPerMember=v;} public Date getReceiveBeginTime(){return receiveBeginTime;} public void setReceiveBeginTime(Date v){receiveBeginTime=v;} public Date getReceiveEndTime(){return receiveEndTime;} public void setReceiveEndTime(Date v){receiveEndTime=v;} public Integer getValidDays(){return validDays;} public void setValidDays(Integer v){validDays=v;} public Date getValidBeginTime(){return validBeginTime;} public void setValidBeginTime(Date v){validBeginTime=v;} public Date getValidEndTime(){return validEndTime;} public void setValidEndTime(Date v){validEndTime=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }
